"""Rule text parsing (SPEC.md section 2)."""

import datetime as dt
import re
from dataclasses import dataclass, field
from decimal import Decimal

from .errors import PlanError, RuleSyntaxError

WEEKDAYS = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]
UNITS = {unit + suffix: unit for unit in ("day", "week", "month") for suffix in ("", "s")}
POSITIVE = r"[1-9][0-9]*"
DATE = r"[0-9]{4}-[0-9]{2}-[0-9]{2}"
TIME = r"[0-9]{2}:[0-9]{2}"
DURATION = re.compile(rf"({POSITIVE}d)?({POSITIVE}h)?({POSITIVE}m)?")


@dataclass
class Rule:
    every: int = 1
    unit: str = "day"
    on: list = field(default_factory=list)   # weekday indexes, or month days / "last"
    at: list = field(default_factory=list)   # datetime.time
    minutes: int = 0
    start: dt.date = None
    until: dt.date = None
    times: int = None


def parse_duration(word):
    """Return the duration in minutes, or None for an invalid value."""
    if not isinstance(word, str) or not word:
        return None
    match = DURATION.fullmatch(word.lower())
    if match is None:
        return None
    return sum(int(Decimal(part[:-1])) * scale
               for part, scale in zip(match.groups(), (1440, 60, 1)) if part)


def format_duration(minutes):
    days, remainder = divmod(minutes, 1440)
    hours, mins = divmod(remainder, 60)
    return "".join(f"{Decimal(value):f}{unit}"
                   for value, unit in ((days, "d"), (hours, "h"), (mins, "m")) if value)


def _count(word):
    return int(Decimal(word)) if re.fullmatch(POSITIVE, word) else None


def _time(word):
    if not re.fullmatch(TIME, word):
        raise ValueError(word)
    return dt.time.fromisoformat(word)


def _date(word):
    return dt.date.fromisoformat(word) if re.fullmatch(DATE, word) else None


def _month_day(word):
    if word == "last":
        return word
    if not re.fullmatch(r"[1-9]|[12][0-9]|3[01]", word):
        raise ValueError(word)
    return int(word)


def _items(word, convert):
    items = [convert(item) for item in word.split(",")]
    return items if len(items) == len(set(items)) else None


class _Words:
    def __init__(self, text):
        self.text = text
        self.words = [(m.group().lower(), m.start()) for m in re.finditer(r"[^ \t]+", text)]
        self.index = 0

    def peek(self):
        return self.words[self.index][0] if self.index < len(self.words) else None

    def fail(self, message):
        position = self.words[self.index][1] if self.index < len(self.words) else len(self.text)
        raise RuleSyntaxError(message, position, text=self.text)

    def expect(self, keyword):
        if self.peek() != keyword:
            self.fail(f"expected '{keyword}'")
        self.index += 1

    def convert(self, what, convert):
        word = self.peek()
        if word is None:
            self.fail(f"expected {what}, found end of rule")
        try:
            value = convert(word)
        except (ValueError, KeyError):
            value = None
        if value is None:
            self.fail(f"expected {what}, found {word!r}")
        self.index += 1
        return value


def parse_rule(text):
    if not isinstance(text, str):
        raise PlanError("rule text must be a string")
    w = _Words(text)
    rule = Rule()
    w.expect("every")
    if w.peek() is not None and re.fullmatch(r"[0-9]+", w.peek()):
        rule.every = w.convert("a count", _count)
    rule.unit = w.convert("a unit", UNITS.__getitem__)
    if w.peek() == "on" and rule.unit != "day":
        w.expect("on")
        if rule.unit == "month":
            rule.on = w.convert("month days", lambda s: _items(s, _month_day))
            rule.on.sort(key=lambda day: 32 if day == "last" else day)
        else:
            rule.on = sorted(w.convert("weekdays", lambda s: _items(s, WEEKDAYS.index)))
    w.expect("at")
    rule.at = sorted(w.convert("times", lambda s: _items(s, _time)))
    w.expect("for")
    rule.minutes = w.convert("a duration", parse_duration)
    w.expect("from")
    rule.start = w.convert("a date", _date)
    if w.peek() == "until":
        w.expect("until")

        def until_date(word):
            date = _date(word)
            return date if date is not None and date >= rule.start else None

        rule.until = w.convert("a date on or after 'from'", until_date)
    elif w.peek() == "times":
        w.expect("times")
        rule.times = w.convert("a count", _count)
    if w.peek() is not None:
        w.fail(f"unexpected token {w.peek()!r}")
    if not rule.on:
        if rule.unit == "week":
            rule.on = [rule.start.weekday()]
        elif rule.unit == "month":
            rule.on = [rule.start.day]
    return rule


def canonical(text):
    rule = parse_rule(text)
    unit = rule.unit if rule.every == 1 else rule.unit + "s"
    out = ["every", f"{Decimal(rule.every):f}", unit]
    if rule.unit == "week":
        out += ["on", ",".join(WEEKDAYS[d] for d in rule.on)]
    elif rule.unit == "month":
        out += ["on", ",".join(str(d) for d in rule.on)]
    out += ["at", ",".join(t.isoformat(timespec="minutes") for t in rule.at)]
    out += ["for", format_duration(rule.minutes)]
    out += ["from", rule.start.isoformat()]
    if rule.until is not None:
        out += ["until", rule.until.isoformat()]
    if rule.times is not None:
        out += ["times", f"{Decimal(rule.times):f}"]
    return " ".join(out)
"""Plan loading (SPEC.md sections 1 and 5)."""

import datetime as dt
import re
from dataclasses import dataclass
from itertools import groupby
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

from .errors import PlanError, RuleSyntaxError
from .expand import candidate_starts, local_instant
from .rules import DATE, TIME, Rule, parse_duration, parse_rule

RULE_ID = re.compile(r"[A-Za-z0-9_-]+")
LOCAL_TIME = re.compile(rf"{DATE}T{TIME}")


@dataclass
class RuleDef:
    index: int
    id: str
    rule: Rule
    tz: ZoneInfo
    priority: int


@dataclass
class Override:
    action: str
    to: int = None
    minutes: int = None


@dataclass
class Plan:
    rules: list
    overrides: dict          # rule id -> {key: Override}
    min_segment: int


def _zone(name, context="plan"):
    if isinstance(name, str):
        try:
            return ZoneInfo(name)
        except (ZoneInfoNotFoundError, ValueError, UnicodeError):
            pass
    raise PlanError(f"{context}: unknown timezone {name!r}")


def _duration(value, context):
    minutes = parse_duration(value)
    if minutes is None:
        raise PlanError(f"{context}: invalid duration {value!r}")
    return minutes


def _load_rules(items, default_tz):
    if not isinstance(items, list):
        raise PlanError("plan rules must be a list")
    rules = {}
    for index, item in enumerate(items):
        if not isinstance(item, dict):
            raise PlanError(f"rule #{index} must be an object")
        rid = item.get("id")
        if not isinstance(rid, str) or not RULE_ID.fullmatch(rid):
            raise PlanError(f"rule #{index} has invalid id {rid!r}")
        if rid in rules:
            raise PlanError(f"duplicate rule id {rid!r}")
        if not isinstance(item.get("rule"), str):
            raise PlanError(f"rule {rid}: rule text must be a string")
        priority = item.get("priority", 0)
        if not isinstance(priority, int) or isinstance(priority, bool):
            raise PlanError(f"rule {rid}: priority must be an integer")
        try:
            rule = parse_rule(item["rule"])
        except RuleSyntaxError as exc:
            raise RuleSyntaxError(f"rule {rid}: {exc}", exc.position, text=exc.text) from exc
        tz = _zone(item["timezone"], f"rule {rid}") if "timezone" in item else default_tz
        rules[rid] = RuleDef(index, rid, rule, tz, priority)
    return rules


def _parse_local(value, context):
    if isinstance(value, str) and LOCAL_TIME.fullmatch(value):
        try:
            return dt.datetime.fromisoformat(value)
        except ValueError:
            pass
    raise PlanError(f"{context}: invalid local date-time {value!r}")


def _validate_keys(ruledef, keys):
    dates = {key: dt.date.fromisoformat(key[:10]) for key in keys}
    if ruledef.rule.times is not None:
        starts = candidate_starts(ruledef, min(dates.values()), max(dates.values()))
        missing = set(dates)
        for key, _ in starts:
            missing.discard(key)
            if not missing:
                return
        raise PlanError(f"rule {ruledef.id}: invalid override key {min(missing)!r}")
    else:
        for day, day_keys in groupby(sorted(dates), key=dates.__getitem__):
            valid = {key for key, _ in candidate_starts(ruledef, day, day)}
            for key in day_keys:
                if key not in valid:
                    raise PlanError(f"rule {ruledef.id}: invalid override key {key!r}")


def _load_overrides(items, rules):
    if not isinstance(items, list):
        raise PlanError("plan overrides must be a list")
    overrides = {}
    for item in items:
        if not isinstance(item, dict):
            raise PlanError("override must be an object")
        rid = item.get("rule")
        if not isinstance(rid, str) or rid not in rules:
            raise PlanError(f"override for unknown rule {rid!r}")
        context = f"rule {rid}"
        ruledef = rules[rid]
        key = item.get("key")
        if len(ruledef.rule.at) == 1 and isinstance(key, str) and re.fullmatch(DATE, key):
            key += "T" + ruledef.rule.at[0].isoformat(timespec="minutes")
        _parse_local(key, f"{context} override key")
        rule_overrides = overrides.setdefault(rid, {})
        if key in rule_overrides:
            raise PlanError(f"{context}: duplicate override for {key!r}")

        action = item.get("action")
        if action == "cancel":
            rule_overrides[key] = Override(action)
        elif action == "move":
            wall = _parse_local(item.get("to"), f"{context} move target")
            minutes = _duration(item["for"], f"{context} move duration") if "for" in item else None
            rule_overrides[key] = Override(action, local_instant(wall, ruledef.tz), minutes)
        else:
            raise PlanError(f"{context}: unknown override action {action!r}")

    for rid, rule_overrides in overrides.items():
        _validate_keys(rules[rid], rule_overrides)
    return overrides


def load_plan(raw):
    if not isinstance(raw, dict):
        raise PlanError("plan must be an object")
    if "timezone" not in raw:
        raise PlanError("plan has no timezone")
    default_tz = _zone(raw["timezone"])
    rules = _load_rules(raw.get("rules"), default_tz)
    overrides = _load_overrides(raw.get("overrides", []), rules)
    min_segment = _duration(raw["min_segment"], "min_segment") if "min_segment" in raw else 0
    return Plan(list(rules.values()), overrides, min_segment)
"""Turn one rule into concrete occurrences (SPEC.md sections 3 and 4)."""

import calendar
import datetime as dt
from dataclasses import dataclass
from math import gcd

SECONDS_PER_DAY = 86400
MONTHS_PER_GREGORIAN_CYCLE = 400 * 12
UTC_ORIGIN = dt.datetime(1, 1, 1, tzinfo=dt.timezone.utc)
LAST_ORDINAL = dt.date.max.toordinal()


@dataclass
class Occurrence:
    rule: object          # RuleDef
    key: str
    start: int            # UTC seconds since 0001-01-01
    end: int


def instant(wall):
    """Convert an aware wall time to UTC seconds without calendar arithmetic."""
    offset = wall.utcoffset() // dt.timedelta(seconds=1)
    return ((wall.toordinal() - 1) * SECONDS_PER_DAY
            + wall.hour * 3600 + wall.minute * 60 + wall.second - offset)


def local_instant(wall, zone):
    # ZoneInfo's fold=0 uses the offset before the transition for both folds
    # and gaps. In a gap that gives the instant after the clock moves forward.
    return instant(wall.replace(tzinfo=zone, fold=0))


def timestamp(seconds, zone):
    try:
        value = (UTC_ORIGIN + dt.timedelta(seconds=seconds)).astimezone(zone)
    except OverflowError:
        # A local date at a calendar boundary can have an out-of-range UTC date.
        edge_day = 1 if seconds < 0 else LAST_ORDINAL - 2
        edge = (UTC_ORIGIN + dt.timedelta(days=edge_day)).astimezone(zone)
        offset = edge.utcoffset()
        value = (UTC_ORIGIN + (dt.timedelta(seconds=seconds) + offset))
        value = value.replace(tzinfo=dt.timezone(offset))
    # Historical zone offsets may contain seconds. The output uses HH:MM.
    formatted = value.isoformat(timespec="seconds")
    offset = formatted[19:25]
    return formatted[:19] + ("+00:00" if offset == "-00:00" else offset)


def nominal_date(seconds, padding):
    """Bound the nominal date using the UTC date and the maximum offset."""
    ordinal = seconds // SECONDS_PER_DAY + 1 + padding
    return dt.date.fromordinal(min(max(ordinal, 1), LAST_ORDINAL))


def _month_index(day):
    return (day.year - 1) * 12 + day.month - 1


def _active_periods(first, last, anchor, step):
    return range(first + (anchor - first) % step, last + 1, step)


def _candidate_dates(rule, first, last):
    first = max(first, rule.start)
    if rule.until is not None:
        last = min(last, rule.until)
    if first > last:
        return

    lo, hi = first.toordinal(), last.toordinal()
    anchor = rule.start.toordinal()
    if rule.unit == "day":
        for ordinal in _active_periods(lo, hi, anchor, rule.every):
            yield dt.date.fromordinal(ordinal)
    elif rule.unit == "week":
        monday = anchor - rule.start.weekday()
        first_week, last_week = (lo - monday) // 7, (hi - monday) // 7
        for week in _active_periods(first_week, last_week, 0, rule.every):
            for weekday in rule.on:
                ordinal = monday + week * 7 + weekday
                if lo <= ordinal <= hi:
                    yield dt.date.fromordinal(ordinal)
    else:
        # The active months repeat after a full Gregorian cycle. If none of
        # them has a selected date, a counted rule can never reach its count.
        cycle = MONTHS_PER_GREGORIAN_CYCLE // gcd(rule.every, MONTHS_PER_GREGORIAN_CYCLE)
        empty_months = 0
        for month in _active_periods(_month_index(first), _month_index(last),
                                     _month_index(rule.start), rule.every):
            year, month = divmod(month, 12)
            year, month = year + 1, month + 1
            last_day = calendar.monthrange(year, month)[1]
            days = {last_day if day == "last" else day
                    for day in rule.on if day == "last" or day <= last_day}
            if not days:
                empty_months += 1
                if empty_months == cycle:
                    return
                continue
            empty_months = 0
            for day in sorted(days):
                date = dt.date(year, month, day)
                if first <= date <= last:
                    yield date


def _day_starts(ruledef, day):
    seen = set()
    for time in ruledef.rule.at:
        wall = dt.datetime.combine(day, time)
        start = local_instant(wall, ruledef.tz)
        if start not in seen:
            seen.add(start)
            yield wall.isoformat(timespec="minutes"), start


def candidate_starts(ruledef, first, last):
    """Yield surviving keys and starts in the requested nominal date range."""
    rule = ruledef.rule
    remaining = rule.times
    scan_from = first if remaining is None else rule.start
    for day in _candidate_dates(rule, scan_from, last):
        for key, start in _day_starts(ruledef, day):
            if day >= first:
                yield key, start
            if remaining is not None:
                remaining -= 1
                if remaining == 0:
                    return
"""Queries over a plan (SPEC.md sections 6 and 7)."""

import datetime as dt
import heapq
import re
from itertools import groupby

from .errors import PlanError
from .expand import Occurrence, candidate_starts, instant, nominal_date, timestamp
from .plan import load_plan
from .rules import DATE, TIME

BOUND = re.compile(rf"{DATE}T{TIME}(?::[0-9]{{2}})?(?:Z|[+-](?:[01][0-9]|2[0-3]):[0-5][0-9])")


def _parse_bound(text):
    if isinstance(text, str) and BOUND.fullmatch(text):
        value = text[:-1] + "+00:00" if text.endswith("Z") else text
        try:
            return instant(dt.datetime.fromisoformat(value))
        except ValueError:
            pass
    raise PlanError(f"invalid date-time {text!r}")


def _window(plan, start, end):
    plan = load_plan(plan)
    lo, hi = _parse_bound(start), _parse_bound(end)
    if lo >= hi:
        raise PlanError("window end must be after start")
    return plan, lo, hi


def _collect(plan, lo, hi):
    for ruledef in plan.rules:
        length = ruledef.rule.minutes * 60
        first = nominal_date(lo - length, -1)
        last = nominal_date(hi, 1)
        overrides = plan.overrides.get(ruledef.id, {})
        for key, start in candidate_starts(ruledef, first, last):
            end = start + length
            if key not in overrides and start < hi and end > lo:
                yield Occurrence(ruledef, key, start, end)
        for key, override in overrides.items():
            if override.action == "move":
                start = override.to
                end = start + (override.minutes * 60 if override.minutes is not None else length)
                if start < hi and end > lo:
                    yield Occurrence(ruledef, key, start, end)


def _as_dict(occ, start, end):
    try:
        return {
            "rule": occ.rule.id,
            "key": occ.key,
            "start": timestamp(start, occ.rule.tz),
            "end": timestamp(end, occ.rule.tz),
        }
    except OverflowError as exc:
        raise PlanError(f"rule {occ.rule.id}: timestamp outside the supported calendar") from exc


def occurrences(plan, start, end):
    plan, lo, hi = _window(plan, start, end)
    ordered = sorted(_collect(plan, lo, hi),
                     key=lambda occ: (occ.start, occ.end, -occ.rule.priority, occ.rule.index, occ.key))
    return [_as_dict(occ, occ.start, occ.end) for occ in ordered]


def _winning_segments(occurrences):
    ranked = sorted(occurrences,
                    key=lambda occ: (-occ.rule.priority, occ.start, occ.rule.index, occ.key))
    events = []
    for rank, occ in enumerate(ranked):
        events.append((occ.start, rank, True))
        events.append((occ.end, rank, False))
    events.sort()

    active = []
    winner = None
    segment_start = None
    # Group simultaneous boundaries so a winner is determined once per instant.
    for time, boundaries in groupby(events, key=lambda event: event[0]):
        for _, rank, is_start in boundaries:
            if is_start:
                heapq.heappush(active, rank)
        while active and ranked[active[0]].end <= time:
            heapq.heappop(active)
        next_winner = active[0] if active else None
        if winner != next_winner:
            if winner is not None:
                yield ranked[winner], segment_start, time
            winner, segment_start = next_winner, time


def agenda(plan, start, end):
    plan, lo, hi = _window(plan, start, end)
    minimum = plan.min_segment * 60
    rows = []
    for occ, left, right in _winning_segments(_collect(plan, lo, hi)):
        length = right - left
        if length == occ.end - occ.start or length >= minimum:
            clipped_start, clipped_end = max(lo, left), min(hi, right)
            if clipped_start < clipped_end:
                rows.append(_as_dict(occ, clipped_start, clipped_end))
    return rows
import json
import sys
from decimal import Decimal

from .errors import PlanError, RuleSyntaxError
from .query import agenda, occurrences
from .rules import canonical


def _invalid_constant(value):
    raise ValueError(f"invalid JSON constant {value!r}")


def _run(argv):
    if len(argv) == 2 and argv[0] == "canonical":
        print(canonical(argv[1]))
        return 0
    if len(argv) != 4 or argv[0] not in ("occurrences", "agenda"):
        print("usage: python3 -m cadence {occurrences,agenda} START END PLAN.json", file=sys.stderr)
        print("       python3 -m cadence canonical RULE", file=sys.stderr)
        return 1

    command, start, end, path = argv
    try:
        with open(path, "rb") as f:
            plan = json.load(f, parse_int=lambda value: int(Decimal(value)),
                             parse_constant=_invalid_constant)
    except (OSError, ValueError, RecursionError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1

    rows = occurrences(plan, start, end) if command == "occurrences" else agenda(plan, start, end)
    if not rows:
        print("nothing scheduled")
    for row in rows:
        print(row["start"], row["end"], row["rule"], row["key"])
    return 0


def main(argv=None):
    try:
        return _run(sys.argv[1:] if argv is None else argv)
    except PlanError as exc:
        print(f"error: {exc}", file=sys.stderr)
        if isinstance(exc, RuleSyntaxError):
            print(exc.text, file=sys.stderr)
            print(" " * exc.position + "^", file=sys.stderr)
        return 2

